from html import escape

def rtw_ui(c,item):
    en=c['lang']=='en'
    return f'''<div class="pui rtw-ui"><div class="pui__bar"><span class="pui__window"><i></i><i></i><i></i></span><span>RTW / QuoteFlow</span><span class="pui__study">{'Fictional example' if en else 'Fiktives Beispiel'}</span></div><div class="rtw-ui__route"><span>{'Air-freight enquiry' if en else 'Luftfrachtanfrage'}</span><strong>ZRH <i>→</i> JFK</strong><small>{'Sample shipment · no customer data' if en else 'Beispielsendung · keine Kundendaten'}</small></div><ol class="rtw-ui__flow"><li><b>01</b>{'Enquiry' if en else 'Anfrage'}</li><li><b>02</b>{'Shipment details' if en else 'Sendungsdaten'}</li><li><b>03</b>{'Supplier offers' if en else 'Angebote'}</li><li><b>04</b>{'Team review' if en else 'Teamprüfung'}</li></ol><div class="rtw-ui__offers"><div><span>{'Offer A' if en else 'Angebot A'}</span><strong>{'Ready to compare' if en else 'Vergleichbar'}</strong><small>{'Charges and conditions together' if en else 'Kosten und Bedingungen zusammen'}</small></div><div><span>{'Offer B' if en else 'Angebot B'}</span><strong>{'Clarification needed' if en else 'Rückfrage offen'}</strong><small>{'A missing detail stays visible' if en else 'Eine fehlende Angabe bleibt sichtbar'}</small></div></div><div class="rtw-ui__review"><i></i>{'Internal review before the next step' if en else 'Interne Prüfung vor dem nächsten Schritt'}</div></div>'''

def mps_ui(c,item):
    en=c['lang']=='en';key='mps-map'
    groups=[('food','#dfbd78',['Crop production','Food access','Supply routes','Input costs'],['Ernteproduktion','Nahrungszugang','Lieferwege','Betriebsmittel']),('climate','#89bcb4',['Rainfall patterns','Water availability','Land use','Heat exposure'],['Niederschlagsmuster','Wasserverfügbarkeit','Landnutzung','Hitzeexposition']),('debt','#b4b48e',['Fiscal space','Debt servicing','FX exposure','Investment access'],['Fiskalischer Spielraum','Schuldendienst','Währungsrisiken','Investitionszugang'])]
    xy=[(20,22),(12,48),(30,67),(38,33),(66,18),(83,36),(70,57),(91,65),(47,77),(54,52),(63,88),(41,13)]
    points=[];labels=[]
    i=0
    for group,color,eng,de in groups:
        for name in (eng if en else de):
            x,y=xy[i];labels.append(f'<button type="button" class="risk-node" style="--x:{x}%;--y:{y}%;--tone:{color}" data-demo-variable="{escape(name,quote=True)}" aria-pressed="false"><i></i><span>{escape(name)}</span></button>');points.append((x,y));i+=1
    edges=[]
    for a,b in [(0,1),(0,3),(1,2),(2,4),(3,5),(4,5),(4,6),(5,7),(6,7),(6,9),(8,9),(8,10),(9,11),(10,11),(0,4),(1,8),(2,9),(3,9),(4,9),(5,10),(6,8),(7,10)]:
        x,y=points[a];xx,yy=points[b];edges.append(f'<line x1="{x}" y1="{y}" x2="{xx}" y2="{yy}"/>')
    return f'''<div class="pui risk-ui" data-variable-demo><div class="pui__bar"><span class="pui__window"><i></i><i></i><i></i></span><span>MPS / Kenya</span><span class="pui__study">{'Illustrative sample' if en else 'Illustratives Beispiel'}</span></div><div class="risk-ui__heading"><span>{'COUNTRY RESEARCH' if en else 'LÄNDERRECHERCHE'}</span><h4>{'A connected view of Kenya.' if en else 'Kenia im Zusammenhang.'}</h4><p>{'Food · Climate · Debt' if en else 'Ernährung · Klima · Verschuldung'}</p></div><div class="risk-ui__map"><svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">{''.join(edges)}</svg>{''.join(labels)}</div><div class="risk-ui__legend"><span><i style="background:#dfbd78"></i>{'Food' if en else 'Ernährung'}</span><span><i style="background:#89bcb4"></i>{'Climate' if en else 'Klima'}</span><span><i style="background:#b4b48e"></i>{'Debt' if en else 'Verschuldung'}</span></div><div class="risk-ui__detail" aria-live="polite"><strong data-variable-name>{'Choose a variable' if en else 'Eine Variable wählen'}</strong><p>{'This sample shows how a variable can connect to evidence and expert review. Colours mark research areas. Connections are illustrative; this is not a country assessment.' if en else 'Dieses Beispiel zeigt, wie sich eine Variable mit Belegen und fachlicher Prüfung verknüpfen lässt. Farben kennzeichnen Recherchebereiche. Die Verbindungen sind illustrativ; dies ist keine Länderbewertung.'}</p></div></div>'''

def evi_gallery(c,item):
    en=c['lang']=='en';items=[('system','System map','Systemkarte'),('variables','Variables','Variablen'),('detail','Detail view','Detailansicht')]
    tabs=''.join(f'<button type="button" role="tab" id="evi-screen-tab-{i}" aria-controls="evi-screen-{i}" aria-selected="{str(i==0).lower()}" tabindex="{0 if i==0 else -1}" data-gallery-tab="{i}">{b if en else d}</button>' for i,(a,b,d) in enumerate(items))
    panels=''.join(f'<div role="tabpanel" id="evi-screen-{i}" aria-labelledby="evi-screen-tab-{i}" tabindex="0" {"hidden" if i else ""}><img data-src="/pilot-assets/evi-{a}.jpg" alt="Earth Voice Index — {b if en else d}; {"illustrative sample data" if en else "illustrative Beispieldaten"}" width="1280" height="649" loading="lazy"><a class="evi-gallery__full" href="/pilot-assets/evi-{a}.jpg" target="_blank" rel="noopener noreferrer">{"Open full-size view" if en else "Ansicht in voller Grösse öffnen"} ↗</a></div>' for i,(a,b,d) in enumerate(items))
    return f'<div class="evi-gallery" data-screen-gallery><div class="pui__tabs" role="tablist" aria-label="Earth Voice Index">{tabs}</div>{panels}</div>'
